const courseQuizBank={"concepts": [{"text": "Un concept utile au raisonnement est :", "options": ["Une idée générale précisément définie.", "Une description qui ne concerne qu’une personne.", "Un outil pour organiser des informations.", "Un synonyme obligatoire de diagnostic médical.", "Une notion dont on peut identifier les attributs."], "answers": [0, 2, 4], "explanation": "Un concept organise l’analyse de plusieurs situations ; ses attributs en précisent le sens."}, {"text": "Les dimensions du métaparadigme infirmier sont :", "options": ["La personne.", "Le budget du service.", "La santé.", "L’environnement.", "Les soins infirmiers."], "answers": [0, 2, 3, 4], "explanation": "Le cadre relie personne, santé, environnement et soins. Le budget peut être un élément du contexte, mais pas un de ces quatre métaconcepts."}, {"text": "Une personne aidée pour se déplacer :", "options": ["Peut conserver son autonomie de décision.", "Est nécessairement incapable de consentir.", "Peut exprimer ses préférences.", "Doit toujours laisser sa famille décider.", "Présente nécessairement une incapacité intellectuelle."], "answers": [0, 2], "explanation": "Besoin d’aide physique et capacité de décision sont deux dimensions différentes."}, {"text": "Quelles associations sont pertinentes ?", "options": ["Modèle : organisation de concepts et relations.", "Théorie : propositions reliant des phénomènes.", "Paradigme : orientation générale de pensée.", "Épistémologie : simple liste des gestes de soins.", "Métaparadigme : prescription propre à un patient."], "answers": [0, 1, 2], "explanation": "L’épistémologie étudie les savoirs ; le métaparadigme est un cadre très général de la discipline."}, {"text": "Pour argumenter une proposition de soins, on peut :", "options": ["Distinguer faits et hypothèses.", "Ignorer les préférences de la personne.", "Rechercher les informations manquantes.", "Relier la situation aux connaissances pertinentes.", "Garder la même conclusion malgré toute nouvelle donnée."], "answers": [0, 2, 3], "explanation": "Un raisonnement explicite relie les données aux connaissances et se réévalue."}], "theories": [{"text": "Une théorie de soins peut :", "options": ["Aider à comprendre un phénomène.", "Remplacer tout recueil de données.", "Orienter des questions cliniques.", "Rendre une intervention explicable.", "Garantir le succès de toute intervention."], "answers": [0, 2, 3], "explanation": "Elle éclaire la pratique mais ne remplace ni l’évaluation de la personne ni celle des résultats."}, {"text": "Quelles associations sont correctes ?", "options": ["Henderson : besoins fondamentaux.", "Orem : autosoins.", "Watson : dimension humaine du caring.", "Kolcaba : téléexpertise médicale.", "Meleis : transitions."], "answers": [0, 1, 2, 4], "explanation": "Kolcaba est associée au confort, et non à la téléexpertise."}, {"text": "Une théorie de portée intermédiaire :", "options": ["Cible un phénomène relativement délimité.", "Doit expliquer toutes les situations humaines.", "Peut aider à étudier le confort.", "Est nécessairement inutile en pratique.", "Peut orienter l’évaluation d’une intervention."], "answers": [0, 2, 4], "explanation": "Sa portée ciblée permet de travailler un phénomène et ses implications pratiques."}, {"text": "Testabilité et soutien empirique :", "options": ["Désignent exactement la même chose.", "Distinguent possibilité de tester et données disponibles.", "Peuvent servir à examiner une théorie.", "Signifient qu’une théorie est toujours vraie.", "Suppriment le besoin d’évaluation clinique."], "answers": [1, 2], "explanation": "On peut formuler une proposition testable sans disposer encore de données qui la soutiennent."}, {"text": "Pour choisir un cadre théorique :", "options": ["Partir d’une question clinique.", "Choisir systématiquement le même auteur.", "Examiner la pertinence des concepts.", "Considérer son utilité pratique.", "Éviter de tenir compte du contexte."], "answers": [0, 2, 3], "explanation": "Le choix doit répondre à la question et à la situation, puis être discuté et évalué."}], "observation": [{"text": "Lesquels sont des constats ?", "options": ["La personne dit avoir peu dormi.", "La personne cherche forcément à attirer l’attention.", "La tasse est restée pleine à la fin du repas.", "Une température de 38 °C a été mesurée.", "La personne est désagréable."], "answers": [0, 2, 3], "explanation": "Une parole rapportée et une mesure sont des données. Une intention supposée ou un jugement ne sont pas des constats."}, {"text": "Une observation active implique :", "options": ["Une attention orientée vers la situation.", "L’utilisation de connaissances pertinentes.", "L’absence de toute réflexion.", "La vérification des hypothèses.", "La certitude immédiate sur toute intention."], "answers": [0, 1, 3], "explanation": "Observer activement permet de relier les indices aux connaissances sans transformer les hypothèses en certitudes."}, {"text": "Quels éléments peuvent influencer la perception ?", "options": ["La fatigue.", "Les émotions.", "Les attentes du soignant.", "Les références culturelles.", "Aucun élément individuel."], "answers": [0, 1, 2, 3], "explanation": "Ces facteurs peuvent orienter l’attention et l’interprétation ; les reconnaître aide à limiter les biais."}, {"text": "Observer globalement puis de façon ciblée permet :", "options": ["D’apprécier l’ensemble de la situation.", "De préciser les indices pertinents.", "D’utiliser une grille comme unique preuve.", "D’ignorer les informations inattendues.", "De compléter les premières observations."], "answers": [0, 1, 4], "explanation": "Une grille structure les informations mais ne remplace pas une attention adaptée à la situation."}, {"text": "Une transmission utile comporte :", "options": ["Le contexte et le moment.", "Des faits précis.", "Des jugements de caractère.", "Les actions réalisées.", "Des hypothèses présentées comme prouvées."], "answers": [0, 1, 3], "explanation": "La transmission doit distinguer les faits des hypothèses et expliquer les actions entreprises."}], "recueil": [{"text": "Le recueil de données recherche :", "options": ["Les attentes.", "Les ressources.", "Uniquement le nom de la maladie.", "Les habitudes pertinentes.", "Les difficultés rencontrées."], "answers": [0, 1, 3, 4], "explanation": "La démarche concerne la personne et ses possibilités, pas seulement la pathologie."}, {"text": "Quelles données sont subjectives ?", "options": ["Une douleur rapportée.", "Une inquiétude exprimée.", "Une température mesurée.", "Un poids obtenu sur une balance.", "Un sentiment de fatigue décrit."], "answers": [0, 1, 4], "explanation": "Les données subjectives décrivent l’expérience rapportée par la personne ; elles restent importantes pour les soins."}, {"text": "Lors d’un entretien, il est utile de :", "options": ["Expliquer son objectif.", "Employer des mots accessibles.", "Poser plusieurs questions en même temps.", "Reformuler les propos.", "Interrompre systématiquement les silences."], "answers": [0, 1, 3], "explanation": "Ces attitudes facilitent l’expression et la compréhension ; les silences et le rythme doivent être respectés."}, {"text": "Les sources complémentaires peuvent comprendre :", "options": ["Le dossier.", "L’équipe.", "L’entourage dans le respect du cadre et de l’accord de la personne.", "Une supposition non vérifiée sur la famille.", "Des informations dont la provenance est précisée."], "answers": [0, 1, 2, 4], "explanation": "Les informations doivent être vérifiées et leur source identifiée ; une supposition n’est pas une donnée établie."}, {"text": "Le recueil de données :", "options": ["S’arrête après l’admission.", "Peut cibler un problème particulier.", "Peut être adapté à une urgence.", "Doit être réévalué.", "Ne tient pas compte d’un changement d’état."], "answers": [1, 2, 3], "explanation": "Il évolue avec la situation et les besoins ; les données initiales servent aussi de base de comparaison."}], "collaboration": [{"text": "La collaboration IDE–AS demande :", "options": ["Un objectif commun.", "Le respect des compétences.", "Des transmissions utiles.", "Le transfert intégral de la responsabilité de l’IDE.", "Un encadrement adapté."], "answers": [0, 1, 2, 4], "explanation": "La coopération associe des professionnels responsables dans leurs cadres respectifs."}, {"text": "Devant une difficulté nouvelle pendant un soin :", "options": ["Décrire les faits.", "Poursuivre automatiquement comme prévu.", "Solliciter une évaluation adaptée.", "Signaler la modification observée.", "Dissimuler la difficulté pour préserver l’équipe."], "answers": [0, 2, 3], "explanation": "Une modification peut nécessiter un ajustement ; la sécurité exige une transmission et une évaluation."}, {"text": "Un soin de la vie quotidienne :", "options": ["S’inscrit dans un contexte stabilisé.", "Est à l’origine réalisable par la personne ou un aidant.", "Est défini seulement par son nom.", "Dispense de prendre en compte l’état clinique.", "Peut nécessiter une aide adaptée aux capacités de la personne."], "answers": [0, 1, 4], "explanation": "Le contexte et les capacités comptent ; une dénomination ne suffit pas à qualifier la situation."}, {"text": "Après un incident, les démarches utiles sont :", "options": ["Protéger la personne.", "Alerter selon la situation.", "Suivre la procédure de signalement.", "Effacer les informations gênantes.", "Participer à l’analyse."], "answers": [0, 1, 2, 4], "explanation": "Protection, alerte, traçabilité et analyse permettent de prendre en charge la situation et d’améliorer la sécurité."}, {"text": "Concernant les responsabilités :", "options": ["L’AS répond de son activité.", "L’IDE conserve ses obligations d’encadrement.", "Une habitude de service autorise tous les gestes.", "Les limites doivent pouvoir être discutées.", "La collaboration supprime toute responsabilité individuelle."], "answers": [0, 1, 3], "explanation": "Ni la coopération ni une habitude ne remplacent le cadre de compétences et les obligations des professionnels."}], "exercice": [{"text": "Avant un acte, il faut examiner :", "options": ["Son habilitation.", "Les conditions requises.", "Les informations nécessaires à la sécurité.", "Seulement la fréquence de l’acte dans le service.", "Le cadre applicable à la situation."], "answers": [0, 1, 2, 4], "explanation": "Une habitude ne suffit pas à justifier un acte ; compétences, conditions et sécurité doivent être réunies."}, {"text": "Une prescription médicale :", "options": ["Supprime toute responsabilité infirmière.", "Doit être suffisamment précise.", "Peut nécessiter une clarification.", "Est toujours utilisable même illisible.", "S’inscrit dans des conditions réglementaires."], "answers": [1, 2, 4], "explanation": "La prescription encadre une action ; celui qui intervient conserve ses obligations professionnelles."}, {"text": "Quelles associations sont pertinentes ?", "options": ["Responsabilité civile : réparation dans un cadre de droit privé.", "Responsabilité pénale : sanction d’une infraction.", "Responsabilité disciplinaire : manquement professionnel.", "Responsabilité administrative : uniquement licenciement privé.", "Plusieurs responsabilités peuvent se cumuler."], "answers": [0, 1, 2, 4], "explanation": "Les régimes ont des finalités et des conditions distinctes ; la responsabilité administrative concerne notamment les services publics."}, {"text": "Une faute disciplinaire :", "options": ["Exige toujours un dommage au patient.", "Peut concerner une obligation professionnelle.", "Est nécessairement un crime.", "Peut exister sans dommage au patient.", "Supprime toute possibilité d’autre responsabilité."], "answers": [1, 3], "explanation": "La discipline porte sur les obligations professionnelles ; elle ne se confond pas avec la réparation d’un dommage ou le pénal."}, {"text": "En télémédecine, il reste nécessaire de :", "options": ["Préserver la confidentialité.", "Être formé aux outils utilisés.", "Assurer une traçabilité adaptée.", "Renoncer à expliquer les soins.", "Maintenir une relation de qualité."], "answers": [0, 1, 2, 4], "explanation": "La distance modifie les outils, pas les exigences de sécurité, d’information et de confidentialité."}], "droits": [{"text": "Un étudiant peut notamment :", "options": ["Demander un accompagnement pédagogique.", "S’informer sur les modalités d’évaluation.", "Utiliser les ressources dans le cadre prévu.", "Diffuser librement les photos de stage.", "Participer à la représentation étudiante."], "answers": [0, 1, 2, 4], "explanation": "Les droits d’apprentissage et de représentation s’exercent dans un cadre qui respecte les personnes et la confidentialité."}, {"text": "Face à une limite de compétence, l’étudiant doit :", "options": ["La reconnaître.", "Demander un encadrement adapté.", "Faire semblant de maîtriser.", "Préserver la sécurité de la personne.", "Éviter d’en parler à l’équipe."], "answers": [0, 1, 3], "explanation": "La progression repose sur un apprentissage encadré et sur l’expression des difficultés."}, {"text": "Le consentement du patient concerne :", "options": ["Un soin réalisé par un étudiant.", "Un examen réalisé en présence d’un étudiant.", "Uniquement les opérations chirurgicales.", "La possibilité de refuser la participation à l’apprentissage.", "Une obligation d’accepter tous les étudiants."], "answers": [0, 1, 3], "explanation": "La personne conserve ses droits ; sa présence dans un lieu de formation ne vaut pas accord automatique."}, {"text": "Quels devoirs concernent la formation et les stages ?", "options": ["Confidentialité.", "Respect des procédures d’absence.", "Usage adapté du matériel.", "Non-discrimination.", "Publication des informations personnelles pour apprendre."], "answers": [0, 1, 2, 3], "explanation": "Le but pédagogique d’un échange ne permet pas une diffusion libre d’informations personnelles."}, {"text": "Quelles associations sont exactes ?", "options": ["R4312-1 : application du code aux étudiants concernés.", "R4312-48 : soins et examens par l’étudiant ou en sa présence.", "Règlement intérieur : organisation locale.", "Convention de stage : cadre du stage.", "Droit à l’image : autorisation automatique de toute photo."], "answers": [0, 1, 2, 3], "explanation": "Le droit à l’image et la confidentialité demandent de vérifier les autorisations et les conditions de diffusion."}], "ethique": [{"text": "L’éthique peut interroger :", "options": ["Le sens de l’action.", "Les conséquences possibles.", "Les valeurs en tension.", "Uniquement le confort de l’équipe.", "Les raisons justifiant une décision."], "answers": [0, 1, 2, 4], "explanation": "La réflexion examine la situation et les points de vue concernés, notamment celui de la personne soignée."}, {"text": "Quelles distinctions sont pertinentes ?", "options": ["Droit : règles organisant la société.", "Déontologie : devoirs professionnels.", "Morale : repères de conduite liés à des valeurs.", "Éthique : questionnement sur l’action.", "Les quatre termes sont toujours interchangeables."], "answers": [0, 1, 2, 3], "explanation": "Ces dimensions sont liées mais n’ont pas exactement le même objet."}, {"text": "Dans une situation de dépendance :", "options": ["La dignité reste entière.", "Les choix doivent être explorés.", "L’autonomie de décision peut subsister.", "La personne perd automatiquement sa volonté.", "L’aide physique autorise à décider systématiquement à sa place."], "answers": [0, 1, 2], "explanation": "La dignité et la capacité de choix ne se déduisent pas du seul besoin d’aide physique."}, {"text": "Une délibération peut comprendre :", "options": ["Établir les faits.", "Écouter le point de vue de la personne.", "Comparer les options et leurs conséquences.", "Évaluer les effets de la décision.", "Écarter d’emblée les avis différents."], "answers": [0, 1, 2, 3], "explanation": "La discussion croise les perspectives et reste ouverte à une réévaluation de la situation."}, {"text": "Concernant les principes éthiques :", "options": ["Bienfaisance : rechercher un bénéfice.", "Non-malfaisance : limiter les préjudices.", "Justice : questionner l’équité.", "Autonomie : prendre en compte les choix de la personne.", "Une réflexion éthique permet d’ignorer toutes les règles."], "answers": [0, 1, 2, 3], "explanation": "Les principes éclairent une situation ; ils ne constituent pas une autorisation de s’affranchir du cadre applicable."}]};
