const retainedOpenQuestions={"concepts":[["Quels sont les quatre métaconcepts de Fawcett ?","Personne, environnement, santé et soins infirmiers."],["À quoi servent les attributs d’un concept ?","À en préciser les caractéristiques et à le reconnaître dans une situation."],["Pourquoi l’environnement entre-t-il dans le raisonnement clinique ?","Il influence la santé, les risques, les capacités de la personne et les possibilités d’action."]],"theories":[["Cite trois grandes théories et trois théories intermédiaires.","Grandes : Orem, Henderson, Watson. Intermédiaires : Meleis, Kolcaba, Mishel (d’autres exemples du cours conviennent)."],["Quelle différence entre testabilité et évaluation empirique ?","Testabilité : possibilité d’observer et mesurer. Évaluation empirique : existence de données soutenant les propositions."],["Quelles théories le cours associe-t-il aux fonctions explicative, interventionnelle et applicative ?","Gordon, gestion des symptômes UCSF et incertitude dans la maladie de Mishel, respectivement."]],"observation":[["Quels sens sont cités dans le cours ?","Vue, ouïe, toucher et odorat."],["Quelle est la différence entre observation globale et affinée ?","La première donne une vue d’ensemble ; la seconde recherche les détails et structure le recueil."],["Pourquoi les émotions peuvent-elles gêner l’observation ?","Elles influencent ce que l’on perçoit et la manière de le comprendre ; il faut repérer cet effet pour rester objectif."]],"recueil":[["Quelles sont les deux interventions de l’examen clinique infirmier ?","Entretien de recueil de données et examen physique."],["Un patient dit « j’ai mal » ; sa température est mesurée. Quels types de données ?","Douleur rapportée : subjective. Température mesurée : objective."],["Quelles sont les trois parties de l’entretien ?","Introduction, corps et conclusion."],["Pourquoi réévaluer le recueil ?","L’état, les besoins et les hypothèses évoluent ; la démarche de soins doit être mise à jour."]],"collaboration":[["Quelles sont les trois missions de l’AS ?","Accompagnement quotidien et social ; collaboration au projet de soins ; prévention des risques et raisonnement clinique interprofessionnel."],["Quels critères définissent les soins de la vie quotidienne ?","Soin initialement réalisable par la personne ou un aidant ET état de santé ou pathologie chronique stabilisés."],["La collaboration retire-t-elle la responsabilité de l’IDE ?","Non. L’IDE conserve sa responsabilité d’encadrement ; l’AS reste responsable de ses actes."],["Que faire après une erreur ?","Protéger, alerter, transmettre des faits, suivre la procédure et contribuer à l’analyse sans dissimuler."]],"exercice":[["Quels critères retenir pour une prescription médicale selon le cours ?","Sauf urgence : écrite, qualitative, quantitative, datée et signée."],["Quels sont les quatre régimes cités ?","Civil, administratif, pénal, professionnel/disciplinaire."],["Quelle différence entre réparation et sanction pénale ?","La réparation compense un dommage ; la sanction pénale punit une infraction."],["Téléexpertise ou téléconsultation : quelle différence ?","Téléexpertise : demande d’avis entre professionnels. Téléconsultation : consultation à distance avec le patient."],["Pourquoi tracer ses soins ?","Pour la continuité, la sécurité et la preuve des actions et informations transmises."]],"droits":[["Quels sont les sept principes Croix-Rouge ?","Humanité, impartialité, neutralité, indépendance, volontariat, unité, universalité."],["Quel article soumet l’étudiant au code de déontologie ?","R4312-1 du Code de la santé publique."],["Un patient peut-il refuser la présence d’un étudiant ?","Oui : son consentement préalable doit être obtenu, y compris pour un examen ou un soin en présence de l’étudiant."],["Quels sont les deux sens de CAC dans le support ?","Conseil académique à l’université ; commission d’acquisition des crédits à l’IFSI."],["Que faire si un soin dépasse ses compétences ?","Identifier sa limite, demander l’aide et l’encadrement nécessaires, et préserver la sécurité de la personne."]],"ethique":[["Quelle différence entre morale et éthique ?","La morale propose des règles de conduite ; l’éthique questionne leurs fondements et le sens d’une action en situation."],["Que désigne la déontologie ?","Les règles et devoirs propres à une profession."],["Quels sont les trois niveaux du cours ?","Métaéthique, éthique normative et éthique descriptive."],["Pourquoi mener une réflexion pluridisciplinaire ?","Pour croiser les points de vue, éclairer le conflit de valeurs et construire une décision responsable, évaluée et réajustée."],["La dépendance fait-elle perdre la dignité ?","Non. Le respect de la dignité s’impose quelle que soit la situation de la personne."]]};
for(const [id,questions] of Object.entries(retainedOpenQuestions)){if(revisionSheets[id])revisionSheets[id].questions=questions}

