ownCourses["calculs-dose"]={"title": "Calculs de doses : unités, proportions et débits", "ue": "B.1", "intro": "Construire un calcul lisible, contrôler les unités et vérifier que le résultat a du sens.", "sections": [["Convertir avant de calculer", ["La masse et le volume sont des grandeurs distinctes : on ne transforme pas directement des milligrammes en millilitres sans connaître la concentration. Les équivalences essentielles sont 1 g = 1 000 mg, 1 mg = 1 000 µg, 1 L = 1 000 mL et 1 cL = 10 mL. Un centimètre cube correspond à un millilitre.", "Exemples nouveaux : 0,18 g = 180 mg ; 35 mg = 0,035 g ; 0,42 L = 420 mL ; 18 cL = 180 mL. Passer vers une unité plus petite augmente la valeur numérique. Une conversion inverse doit retrouver la quantité initiale.", "Pour les durées, 1 h = 60 min. Une durée de 1 h 30 vaut 1,5 h ou 90 minutes ; elle ne vaut pas 1,30 h. Il faut convertir le temps dans l’unité du débit demandé."]], ["Déduire un volume à partir d’une quantité", ["La proportionnalité relie quantité et volume pour une solution homogène de concentration donnée. Volume à prélever = quantité recherchée / concentration. Les unités peuvent confirmer la méthode : mg ÷ (mg/mL) donne mL.", "Exercice fictif : une solution contient 120 mg dans 6 mL. Sa concentration est 20 mg/mL. Pour une quantité de 70 mg, le volume calculé est 70 / 20 = 3,5 mL. Le même résultat s’obtient par produit en croix : 70 × 6 / 120.", "Le passage par un millilitre ou le produit en croix sont deux méthodes pour une même relation. Éviter d’appliquer une règle mécanique sans identifier ce que chaque nombre représente."]], ["Calculer une dose quotidienne et une dose par prise", ["Une consigne en mg/kg/jour décrit une quantité totale quotidienne liée au poids. Dans un exercice, une consigne fictive de 18 mg/kg/jour pour une masse de 20 kg donne 18 × 20 = 360 mg/jour. Si l’énoncé prévoit trois administrations égales, chaque administration contient 360 / 3 = 120 mg.", "À une concentration de 30 mg/mL, le volume correspondant à une administration de cet exercice est 120 / 30 = 4 mL. Ces chiffres servent à travailler les proportions ; ils ne constituent pas une posologie de médicament réel.", "Ne pas confondre mg/kg/jour et mg/kg/administration. Vérifier également si la quantité indiquée désigne un principe actif ou plusieurs substances, et distinguer quantité par prise, fréquence et durée."]], ["Calculer un débit en mL/h", ["Un débit est un volume divisé par une durée. Pour 360 mL en 3 h : 360 / 3 = 120 mL/h. Pour 90 mL en 45 minutes : convertir 45 min en 0,75 h, puis 90 / 0,75 = 120 mL/h.", "Le volume à prendre en compte est celui explicitement prévu dans l’énoncé ou la préparation. L’arrondi dépend de la précision de l’appareil et des règles de l’exercice ou du service ; il n’existe pas de règle imposant toujours d’arrondir vers le haut.", "Contrôle inverse : débit × durée doit retrouver le volume. Avec 120 mL/h durant 0,75 h, on obtient bien 90 mL."]], ["Passer aux gouttes par minute", ["Pour une perfusion par gravité : gouttes/min = volume en mL × facteur de gouttes / durée en minutes. Le facteur est indiqué sur le dispositif. Un perfuseur peut avoir, par exemple, 20 gouttes/mL ; ce nombre n’est pas universel.", "Avec un facteur explicitement donné de 20 gouttes/mL, 240 mL en 2 h donnent (240 × 20) / 120 = 40 gouttes/min. Avec un facteur de 60 gouttes/mL pour le même volume et la même durée, le nombre de gouttes/min serait trois fois plus grand.", "Un résultat en gouttes/min ne se confond pas avec un débit en mL/h. Les dispositifs, le liquide, la surveillance et les procédures déterminent les conditions réelles d’utilisation."]], ["Faire un bilan et contrôler la cohérence", ["Pour un bilan entrées–sorties, convertir toutes les quantités dans la même unité. Exemple fictif sur une période définie : 900 mL de perfusion + 45 cL de boisson donnent 1 350 mL d’entrées. Si les sorties retenues dans l’énoncé sont de 1,1 L, le bilan arithmétique est 1 350 − 1 100 = +250 mL.", "Un bilan positif signifie que les entrées comptabilisées dépassent les sorties comptabilisées ; il ne permet pas à lui seul de conclure à une maladie. La période, les pertes estimées et la fiabilité du recueil comptent.", "Avant de retenir un résultat : identifier la donnée demandée, convertir, poser le calcul avec les unités, estimer l’ordre de grandeur puis vérifier par une méthode inverse. En situation réelle, toute incohérence demande clarification et contrôle selon le cadre du service avant l’administration."]]], "takeaways": ["Convertir les unités avant les opérations.", "Volume = quantité / concentration.", "Dose quotidienne et dose par administration sont différentes.", "mL/h = volume / heures ; gouttes/min = volume × facteur / minutes.", "Contrôler le résultat et préciser la règle d’arrondi."]};
revisionSheets["calculs-dose"]={"intro": "Construire un calcul lisible, contrôler les unités et vérifier que le résultat a du sens.", "sections": [["Formules et idées essentielles", ["Convertir les unités avant les opérations.", "Volume = quantité / concentration.", "Dose quotidienne et dose par administration sont différentes.", "mL/h = volume / heures ; gouttes/min = volume × facteur / minutes.", "Contrôler le résultat et préciser la règle d’arrondi."]]], "pitfalls": ["Toujours distinguer la donnée, le calcul et son interprétation.", "Une fiche ne remplace pas la lecture des explications et des conditions de l’exercice."], "questions": [["Comment obtenir un volume à partir de mg et de mg/mL ?", "Diviser la quantité en mg par la concentration en mg/mL : le résultat est en mL."], ["Convertis 1 h 45 en heures et minutes.", "1,75 h ou 105 min."], ["Calcule 300 mL sur 2 h 30 en mL/h.", "300/2,5 = 120 mL/h."], ["Quelles informations faut-il pour un débit en gouttes/min ?", "Volume en mL, durée en minutes et facteur de gouttes du dispositif."]], "pages": "Cours rédigé pour cet espace."};
courseQuizBank["calculs-dose"]=[{"text": "Quelles conversions sont correctes ?", "options": ["0,18 g = 180 mg.", "18 cL = 180 mL.", "1 cm³ = 1 mL.", "1 mg = 1 000 µg.", "1 h 30 = 1,30 h."], "answers": [0, 1, 2, 3], "explanation": "1 h 30 = 1,5 h. Les autres équivalences sont correctes."}, {"text": "Une solution de 120 mg dans 6 mL permet de calculer :", "options": ["20 mg/mL.", "3,5 mL pour 70 mg.", "70 × 6 / 120 mL pour 70 mg.", "20 mL pour 70 mg.", "Une quantité de 40 mg dans 2 mL."], "answers": [0, 1, 2, 4], "explanation": "La concentration est 120/6 = 20 mg/mL ; quantité = concentration × volume."}, {"text": "Exercice fictif : 18 mg/kg/jour pour 20 kg en trois administrations égales :", "options": ["360 mg/jour.", "120 mg par administration.", "360 mg à chaque administration.", "4 mL par administration si la solution est à 30 mg/mL.", "La dose quotidienne doit être distinguée de la dose par prise."], "answers": [0, 1, 3, 4], "explanation": "18 × 20 = 360 mg/jour ; 360/3 = 120 mg ; 120/30 = 4 mL. Cela n’est pas une posologie réelle."}, {"text": "90 mL en 45 minutes correspondent à :", "options": ["0,75 heure.", "120 mL/h.", "2 mL/min.", "90 mL/h.", "Une vérification inverse : 120 × 0,75 = 90."], "answers": [0, 1, 2, 4], "explanation": "45/60 = 0,75 h ; 90/0,75 = 120 mL/h ; 90/45 = 2 mL/min."}, {"text": "240 mL en 2 h avec un facteur donné de 20 gouttes/mL :", "options": ["4 800 gouttes au total.", "120 minutes.", "40 gouttes/min.", "120 mL/h.", "20 gouttes/min."], "answers": [0, 1, 2, 3], "explanation": "240 × 20 / 120 = 40 gouttes/min ; 240/2 = 120 mL/h."}, {"text": "Pour calculer un débit en gouttes/min :", "options": ["Lire le facteur du dispositif.", "Convertir la durée en minutes.", "Utiliser le volume en mL.", "Supposer que tous les dispositifs donnent 20 gouttes/mL.", "Multiplier volume par facteur puis diviser par durée."], "answers": [0, 1, 2, 4], "explanation": "Le facteur dépend du dispositif ; il doit être donné ou lu sur le matériel."}, {"text": "Un bilan fictif de 900 mL + 45 cL en entrées et 1,1 L en sorties donne :", "options": ["1 350 mL d’entrées.", "1 100 mL de sorties.", "+250 mL.", "Un bilan positif des quantités comptabilisées.", "La preuve certaine d’une insuffisance cardiaque."], "answers": [0, 1, 2, 3], "explanation": "Le bilan est un résultat arithmétique contextualisé ; il ne pose pas à lui seul un diagnostic."}, {"text": "Les contrôles utiles comprennent :", "options": ["Vérifier les unités.", "Estimer l’ordre de grandeur.", "Retrouver le volume par débit × durée.", "Arrondir toujours vers le haut.", "Clarifier une incohérence avant l’administration."], "answers": [0, 1, 2, 4], "explanation": "Les règles d’arrondi dépendent de la précision du matériel et du cadre prévu."}];
